async function loadData(){try{const r=await fetch('/data.json',{cache:'no-store'});if(!r.ok)throw Error('data.json missing');const j=await r.json();dataGenerated=j.generated||null;bandsData=j.bands||[];names=bandsData.map(b=>b.name).sort((a,b)=>a.localeCompare(b));bandMap={};bandsData.forEach(b=>bandMap[b.name]=b);const summary=getProvinceSummary();el('statN').textContent=summary.tracked;el('statP').textContent=summary.parsedFilings;renderProvinceSummary(summary);renderRecentlyUpdated();renderChips();await restoreRoute(true)}catch(e){el('statN').textContent='-';el('statP').textContent='-';if(el('recentList'))el('recentList').innerHTML='<div class="trend-empty">Update information is not available.</div>'}}
