function recentTimestamp(band,filing){return filing.reparsed||filing.updated||band.scraped||null}
function renderRecentlyUpdated(){const entries=[];bandsData.forEach(b=>{const filings=remFilingsByYear(b).filter(hasRows),explicit=filings.filter(f=>f.reparsed||f.updated);if(explicit.length)explicit.forEach(f=>entries.push({band:b,filing:f,updated:f.reparsed||f.updated}));else if(filings[0]&&b.scraped)entries.push({band:b,filing:filings[0],updated:b.scraped})});entries.sort((a,b)=>String(b.updated).localeCompare(String(a.updated))||String(b.filing.year).localeCompare(String(a.filing.year)));const chosen=[],seenBands=new Set();for(const entry of entries){if(seenBands.has(entry.band.id))continue;seenBands.add(entry.band.id);chosen.push(entry);if(chosen.length===6)break}el('recentList').innerHTML='';if(!chosen.length){el('recentList').innerHTML='<div class="trend-empty">Recent update metadata will appear after future parsing runs.</div>';return}chosen.forEach(entry=>{const item=document.createElement('div');item.className='recent-item';const status=getFilingStatus(entry.filing);item.innerHTML=`<div class="recent-main">${nationLogoMarkup(entry.band,'medium')}<div><div class="recent-name">${esc(entry.band.name)}</div><div class="recent-meta">${esc(entry.filing.year)} · ${esc(status.label)} · ${esc(timeAgo(entry.updated))}</div></div></div><button class="recent-btn">View profile</button>`;item.querySelector('button').onclick=()=>pick(entry.band.name,entry.filing.year);el('recentList').appendChild(item)})}
function renderChips(){el('chips').innerHTML='';let shown=names.filter(n=>remFilings(bandMap[n]||{}).some(isReliableParsed)).slice(0,6);if(!shown.length)shown=names.slice(0,6);shown.forEach(n=>{const d=document.createElement('div');d.className='chip';d.innerHTML=`${nationLogoMarkup(bandMap[n],'tiny')}<span>${esc(n)}</span>`;d.onclick=()=>pick(n);el('chips').appendChild(d)})}
function newsArticles(){return (newsData&&newsData.articles||[]).filter(a=>a&&a.title&&a.url&&/^(SK|Saskatchewan)$/i.test(String(a.provinceTerritory||a.province||'SK'))).slice().sort((a,b)=>String(b.publishedAt||'').localeCompare(String(a.publishedAt||'')))}
function newsCommunitySources(){return newsData&&newsData.communitySources||[]}
function newsSourcesForBand(band){return newsCommunitySources().find(source=>String(source.bandId)===String(band.id)||source.communityName===band.name)||null}
function normalizeCommunityName(value){return String(value||'').normalize('NFKD').replace(/[\u0300-\u036f]/g,'').toLowerCase().replace(/&/g,' and ').replace(/['’]/g,'').replace(/\b(first nations?|cree nation|dene nation|dakota nation|nakoda nation|saulteaux nation|indian band)\b/g,' ').replace(/[^a-z0-9]+/g,' ').trim()}
function articleMatchesCommunity(article,band){if(!article||!band)return false;if(article.bandId!=null&&String(article.bandId)===String(band.id))return true;const target=normalizeCommunityName(band.name);if(!target)return false;const identities=[article.communityName,article.community,...(article.communityAliases||[])].map(normalizeCommunityName).filter(Boolean);return identities.includes(target)}
function newsCategory(article){return article.category||'Other'}
function dedupeKey(article){return String(article.storyKey||article.canonicalKey||article.url||article.id||article.title).toLowerCase().replace(/[^a-z0-9]+/g,'-')}
function filteredNews(){const seen=new Set(),rows=[];newsArticles().forEach(article=>{const key=dedupeKey(article);if(seen.has(key))return;seen.add(key);rows.push(article)});return rows}
function articleDate(article){if(!article.publishedAt)return'Undated';const raw=String(article.publishedAt),parts=/^(\d{4})-(\d{2})-(\d{2})$/.exec(raw),date=parts?new Date(Number(parts[1]),Number(parts[2])-1,Number(parts[3])):new Date(raw);return Number.isFinite(date.getTime())?date.toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric'}):'Undated'}
function sourceTypeLabel(article){const type=String(article.sourceType||'news').replace(/[-_]/g,' ');return type.replace(/\b\w/g,m=>m.toUpperCase())}
function newsCard(article){const source=article.sourceName||article.publication||'Source',summary=article.summary||'',alts=Array.isArray(article.alternateSources)?article.alternateSources.length:0;return`<article class="news-card"><div class="news-card-body"><div class="news-meta"><span>${esc(article.communityName||'Saskatchewan First Nations')}</span><span>·</span><span>${esc(source)}</span><span>·</span><span>${esc(articleDate(article))}</span></div><h2>${esc(article.title)}</h2><p>${esc(summary)}</p><div class="news-card-actions"><span><span class="news-source-type">${esc(sourceTypeLabel(article))}</span> <span class="news-category">${esc(newsCategory(article))}</span>${alts?` <span class="news-category">${alts+1} sources</span>`:''}</span><a class="small-btn" href="${esc(article.url)}" target="_blank" rel="noopener">Original Source</a></div></div></article>`}
function renderNewsPage(){const grid=el('newsGrid');if(!grid)return;const rows=activeNewsCommunity?filteredNews().filter(article=>articleMatchesCommunity(article,activeNewsCommunity)):filteredNews(),shown=rows.slice(0,newsVisible),heading=el('newsPage').querySelector('.news-hero h1'),intro=el('newsPage').querySelector('.news-hero p');heading.textContent=activeNewsCommunity?`${activeNewsCommunity.name} Updates`:'Saskatchewan Updates';intro.textContent=activeNewsCommunity?`Dated public updates currently indexed for ${activeNewsCommunity.name}.`:'Public updates connected to Saskatchewan First Nations from official community channels, organizations, government releases, and reputable news outlets.';grid.innerHTML=shown.length?shown.map(newsCard).join(''):`<div class="news-empty">${activeNewsCommunity?`No dated public update is indexed for ${esc(activeNewsCommunity.name)} yet.`:'No Saskatchewan public updates are loaded yet.'}</div>`;el('newsMoreBtn').style.display=rows.length>newsVisible?'inline-flex':'none'}
