const TREATY_MAP_COLORS={'Treaty 4':'#1f6b3a','Treaty 5':'#2f6fa3','Treaty 6':'#c18420','Treaty 8':'#7b5a93','Treaty 10':'#b34e42','Treaty not listed':'#6f7471'};
const COUNCIL_MAP_COLORS=['#1f6b3a','#2f6fa3','#c18420','#7b5a93','#b34e42','#3f7b75','#7a6c3e','#a85f78','#4f6280','#8b5e3c','#566b42','#806554'];
