const RESERVE_LAND_URL='https://data.sac-isc.gc.ca/geomatics/rest/services/ILRS_PRD/ERIP_E_NRCan/MapServer/26/query?where=CPC_CODE%3D%27SK%27&outFields=ADMIN_LAND_ID%2CSHORT_NAME%2CENAME%2CADMIN_LAND_TYPE%2CCPC_CODE%2CFIRST_NATIONS&returnGeometry=true&outSR=4326&f=geojson&maxAllowableOffset=0.001&resultRecordCount=2000';
