function stableMapColor(value){let hash=0;for(const char of String(value||''))hash=((hash<<5)-hash)+char.charCodeAt(0)|0;return COUNCIL_MAP_COLORS[Math.abs(hash)%COUNCIL_MAP_COLORS.length]}
