function pointOnRingBoundary(point,ring){const[x,y]=point,epsilon=1e-9;for(let index=0,previous=ring.length-1;index<ring.length;previous=index++){const[aX,aY]=ring[previous],[bX,bY]=ring[index],cross=(x-aX)*(bY-aY)-(y-aY)*(bX-aX),scale=Math.max(1,Math.abs(bX-aX),Math.abs(bY-aY));if(Math.abs(cross)>epsilon*scale)continue;if(x>=Math.min(aX,bX)-epsilon&&x<=Math.max(aX,bX)+epsilon&&y>=Math.min(aY,bY)-epsilon&&y<=Math.max(aY,bY)+epsilon)return true}return false}
function pointInRing(point,ring){const[x,y]=point;let inside=false;for(let index=0,previous=ring.length-1;index<ring.length;previous=index++){const[aX,aY]=ring[index],[bX,bY]=ring[previous];if((aY>y)!==(bY>y)&&x<(bX-aX)*(y-aY)/(bY-aY)+aX)inside=!inside}return inside}
function pointTouchesOrInsidePolygon(point,rings){if(!rings||!rings.length)return false;if(rings.some(ring=>pointOnRingBoundary(point,ring)))return true;if(!pointInRing(point,rings[0]))return false;return!rings.slice(1).some(ring=>pointInRing(point,ring))}
function reserveFeatureTouchesCommunity(feature,points){const geometry=feature&&feature.geometry;if(!geometry)return false;const polygons=geometry.type==='Polygon'?[geometry.coordinates]:geometry.type==='MultiPolygon'?geometry.coordinates:[];return points.some(point=>polygons.some(rings=>pointTouchesOrInsidePolygon(point,rings)))}
function reserveLandFeaturesAtCommunityDots(rows=null){const visibleIds=rows?new Set(rows.map(band=>String(band.id))):null,points=(mapData.communities||[]).filter(record=>(!visibleIds||visibleIds.has(String(record.id)))&&Number.isFinite(Number(record.longitude))&&Number.isFinite(Number(record.latitude))).map(record=>[Number(record.longitude),Number(record.latitude)]);return(reserveLandData.features||[]).filter(feature=>reserveFeatureTouchesCommunity(feature,points))}
function renderReserveLandLayer(rows=null){if(!directoryMap||!window.L||!reserveLandData)return;if(directoryReserveLayer)directoryReserveLayer.remove();const features=reserveLandFeaturesAtCommunityDots(rows),mapNode=el('directoryMap');if(mapNode)mapNode.dataset.reserveParcelCount=String(features.length);directoryReserveLayer=window.L.geoJSON({...reserveLandData,features},{pane:'reserveLands',style:RESERVE_LAND_STYLE,onEachFeature:(feature,layer)=>{const properties=feature.properties||{},land=properties.SHORT_NAME||properties.ENAME||'Reserve land',nation=properties.FIRST_NATIONS||'First Nation';layer.bindTooltip(`<div class="map-tooltip map-land-tooltip"><strong>${esc(land)}</strong><span>${esc(nation)}</span><small>First Nation / reserve land</small></div>`,{sticky:true,opacity:1})}}).addTo(directoryMap);directoryReserveLayer.bringToBack()}
function renderMapLegend(rows){const legend=el('mapLegend');if(!legend)return;const counts=new Map();rows.forEach(band=>{const record=directoryMapRecord(band);if(!record)return;const group=directoryMapGroup(band,record);counts.set(group,(counts.get(group)||0)+1)});const entries=[...counts.entries()].sort((a,b)=>directoryMapMode==='treaty'?(parseInt(a[0].replace(/\D/g,''),10)||999)-(parseInt(b[0].replace(/\D/g,''),10)||999):a[0].localeCompare(b[0]));legend.innerHTML=`<div class="map-legend-title">Community markers by ${directoryMapMode==='treaty'?'treaty':'tribal council'}</div>${entries.map(([group,count])=>`<button type="button" class="map-legend-item" data-map-group="${escAttr(group)}" title="Show only ${escAttr(group)}"><span class="map-swatch" style="background:${directoryMapColor(group)}"></span><span>${esc(group)}</span><small>${count}</small></button>`).join('')}`}
function ensureDirectoryMap(){if(directoryMap){setTimeout(()=>directoryMap.invalidateSize(),0);return directoryMap}if(!window.L||!el('directoryMap'))return null;directoryMap=window.L.map('directoryMap',{preferCanvas:true,minZoom:4,maxZoom:16,maxBounds:PRAIRIE_MAP_BOUNDS,maxBoundsViscosity:1,zoomControl:false,scrollWheelZoom:true,touchZoom:true,doubleClickZoom:false,zoomDelta:.5,zoomSnap:.5,wheelPxPerZoomLevel:140});window.L.control.zoom({position:'topright'}).addTo(directoryMap);window.L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:16,noWrap:true,bounds:PRAIRIE_MAP_BOUNDS,attribution:'&copy; OpenStreetMap contributors'}).addTo(directoryMap);window.L.control.scale({imperial:false,position:'bottomleft'}).addTo(directoryMap);const reservePane=directoryMap.createPane('reserveLands');reservePane.style.zIndex='350';directoryLayer=window.L.layerGroup().addTo(directoryMap);directoryMap.fitBounds(PRAIRIE_MAP_BOUNDS,{padding:[8,8]});if(reserveLandData)renderReserveLandLayer();if(el('mapLoading'))el('mapLoading').hidden=true;return directoryMap}
function renderDirectoryMap(rows){if(!directoryMap||!directoryLayer||!window.L){renderMapLegend(rows);return}directoryLayer.clearLayers();if(reserveLandData)renderReserveLandLayer(rows);const points=[];rows.forEach(band=>{const record=directoryMapRecord(band);if(!record||!Number.isFinite(Number(record.latitude))||!Number.isFinite(Number(record.longitude)))return;const point=[Number(record.latitude),Number(record.longitude)],group=directoryMapGroup(band,record),council=record.tribalCouncil||'No council affiliation listed',marker=window.L.circleMarker(point,{radius:9,weight:2,color:'#fff',fillColor:directoryMapColor(group),fillOpacity:.94});points.push(point);marker.bindTooltip(`<div class="map-tooltip"><strong>${esc(band.name)}</strong><span>${esc(band.treaty||'Treaty not listed')}</span><span>${esc(council)}</span><small>Select to open overview</small></div>`,{direction:'top',offset:[0,-9],opacity:1});marker.on('click',()=>location.assign(profilePath(band.name)));marker.on('add',()=>{const node=marker.getElement();if(!node)return;node.setAttribute('role','link');node.setAttribute('tabindex','0');node.setAttribute('aria-label',`Open ${band.name} overview`);node.addEventListener('keydown',event=>{if(event.key==='Enter'||event.key===' '){event.preventDefault();location.assign(profilePath(band.name))}})});marker.addTo(directoryLayer)});const filtered=el('directorySearch').value||el('treatyFilter').value||el('tribalCouncilFilter').value;if(filtered&&points.length){const bounds=window.L.latLngBounds(points);directoryMap.fitBounds(bounds.pad(.18),{maxZoom:8,padding:[24,24]})}renderMapLegend(rows)}
function renderDirectory(){const query=el('directorySearch').value.trim().toLowerCase(),treaty=el('treatyFilter').value,council=el('tribalCouncilFilter').value;const rows=bandsData.filter(band=>{const record=directoryMapRecord(band),affiliation=record&&record.tribalCouncil||'No affiliation listed';return(!query||band.name.toLowerCase().includes(query))&&(!treaty||String(band.treaty||'')===treaty)&&(!council||affiliation===council)}).sort((a,b)=>a.name.localeCompare(b.name));el('directoryCount').textContent=`${rows.length} communit${rows.length===1?'y':'ies'} shown`;el('directoryEmpty').hidden=rows.length>0;el('directoryList').innerHTML=`<div class="directory-community-list">${rows.map(b=>{const state=directoryStatus(b),record=directoryMapRecord(b),councilText=record&&record.tribalCouncil||'No council affiliation listed in current sources';return`<a class="directory-community" href="${profilePath(b.name)}"><span class="directory-community-main">${nationLogoMarkup(b,'medium')}<span><strong>${esc(b.name)}</strong><small>${esc(b.treaty||'Treaty not listed')} · ${esc(councilText)}</small></span></span><span class="directory-status status-${state.key}">${esc(state.label)}</span></a>`}).join('')}</div>`;renderDirectoryMap(rows)}
async function showDirectoryPage(options={}){setView('directory');setDocumentMeta('Explore Saskatchewan First Nations | OpenBand','Explore Saskatchewan First Nations on an interactive map with red First Nation and reserve land boundaries, organized by Treaty and tribal-council affiliation.','/browse/');await Promise.all([loadCapitalData(),loadMapData()]);const treatySelect=el('treatyFilter'),councilSelect=el('tribalCouncilFilter');if(treatySelect.options.length===1){[...new Set(bandsData.map(b=>b.treaty).filter(Boolean))].sort().forEach(treaty=>treatySelect.add(new Option(treaty,treaty)))}if(councilSelect.options.length===1){[...new Set((mapData.communities||[]).map(row=>row.tribalCouncil||'No affiliation listed'))].sort().forEach(council=>councilSelect.add(new Option(council,council)))}el('coverageCount').textContent=`${bandsData.length} of 74`;try{await loadLeaflet();ensureDirectoryMap();try{await loadReserveLandData();renderReserveLandLayer()}catch(error){console.warn('Reserve land boundaries unavailable',error)}}catch(error){if(el('mapLoading'))el('mapLoading').textContent='Interactive map unavailable. Use the community list below.';const fallback=document.querySelector('.map-list-fallback');if(fallback)fallback.open=true}renderDirectory();if(!options.history&&!restoringRoute)history.pushState({page:'directory'},'','/browse/');if(options.scroll!==false)window.scrollTo({top:0,behavior:'smooth'})}
async function restoreRoute(initial=false){const route=currentRoute();restoringRoute=true;try{if(location.hash==='#news'||route.page==='news'||location.pathname==='/news/'||location.pathname==='/news/index.html'){await showNewsPage('',{history:true,scroll:!initial});return}if(route.page==='directory'||location.pathname==='/browse/'||location.pathname==='/browse/index.html'){await showDirectoryPage({history:true,scroll:!initial});return}if(route.bandId||route.slug){const band=bandsData.find(b=>String(b.id)===route.bandId)||bandsData.find(b=>slugify(b.name)===route.slug);if(band){await pick(band.name,route.year,{tab:route.tab,history:true,scroll:!initial});return}}if(route.q){const match=names.find(n=>n.toLowerCase()===route.q.toLowerCase())||names.find(n=>n.toLowerCase().includes(route.q.toLowerCase()));if(match){await pick(match,null,{tab:'overview',history:false,scroll:!initial});return}}showMainPage(true,{history:true});if(location.hash==='#how'&&el('how'))el('how').scrollIntoView()}finally{restoringRoute=false}}
function communityNews(band,limit=3){return newsArticles().filter(article=>articleMatchesCommunity(article,band)).slice(0,limit)}
function renderCommunityNewsSection(band){const rows=communityNews(band,3),encoded=encodeURIComponent(band.name),sourceRecord=newsSourcesForBand(band),official=sourceRecord&&(sourceRecord.sources||[]).find(source=>source.status==='verified'),sourceNote=official?`No dated update is indexed yet. Review the <a href="${esc(official.url)}" target="_blank" rel="noopener">official community source</a>.`:'No dated community update is indexed yet.';return`<section class="profile-news"><div class="section-head"><div><h3>Recent News</h3><p>Latest dated public updates connected specifically to ${esc(band.name)}.</p></div></div>${rows.length?`<div class="profile-news-list">${rows.map(article=>`<a class="profile-news-item" href="${esc(article.url)}" target="_blank" rel="noopener"><div class="profile-news-meta">${esc(articleDate(article))} · ${esc(article.sourceName||'Source')}</div><h4>${esc(article.title)}</h4><p>${esc(article.summary||'')}</p></a>`).join('')}</div>`:`<div class="trend-empty">${sourceNote}</div>`}<div class="profile-news-actions"><button class="small-btn" type="button" onclick="showNewsPage(decodeURIComponent('${encoded}'))">View community news</button></div></section>`}

function eventMatchesCommunity(event,band){return articleMatchesCommunity(event,band)}
function eventDateLabel(event){const start=String(event.startDate||''),end=String(event.endDate||''),format=value=>{const parts=/^(\d{4})-(\d{2})-(\d{2})$/.exec(value);if(!parts)return value;return new Date(Number(parts[1]),Number(parts[2])-1,Number(parts[3])).toLocaleDateString('en-CA',{month:'short',day:'numeric',year:'numeric'})};return end&&end!==start?`${format(start)} – ${format(end)}`:format(start)}
function communityEvents(band,limit=3){const statuses=new Set(['Upcoming','Ongoing','Recently held']);return(eventsData&&eventsData.events||[]).filter(event=>event&&event.title&&event.sourceUrl&&event.startDate&&statuses.has(event.status)&&eventMatchesCommunity(event,band)).slice().sort((a,b)=>{const aPast=a.status==='Recently held',bPast=b.status==='Recently held';return aPast!==bPast?aPast-bPast:aPast?String(b.startDate).localeCompare(String(a.startDate)):String(a.startDate).localeCompare(String(b.startDate))}).slice(0,limit)}
function eventsSourcesForBand(band){return(eventsData&&eventsData.communitySources||[]).find(source=>String(source.bandId)===String(band.id)||source.communityName===band.name)||null}
function renderCommunityEventsSection(band){const rows=communityEvents(band,3),sourceRecord=eventsSourcesForBand(band),official=sourceRecord&&(sourceRecord.sources||[]).find(source=>source.status==='verified'&&source.url),empty=official?`No current dated event has been indexed. Check the <a href="${esc(official.url)}" target="_blank" rel="noopener">official community source</a> for late changes.`:'No current dated event has been indexed from a verified public source.';return`<section class="profile-events" aria-labelledby="communityEventsHeading"><div class="section-head"><div><h3 id="communityEventsHeading">Community Events</h3><p>Upcoming and recently held public events from community sources.</p></div>${rows.length?`<span class="event-count">${rows.length} shown</span>`:''}</div>${rows.length?`<div class="profile-events-list">${rows.map(event=>`<a class="profile-event-item" href="${esc(event.sourceUrl)}" target="_blank" rel="noopener"><div class="event-date"><strong>${esc(eventDateLabel(event))}</strong><span>${esc(event.status)}</span></div><div class="event-body"><div class="profile-event-meta">${esc(event.category||'Community Event')} · ${esc(event.sourceName||'Source')}</div><h4>${esc(event.title)}</h4>${event.location?`<p>${esc(event.location)}</p>`:''}</div></a>`).join('')}</div>`:`<div class="trend-empty">${empty}</div>`}<p class="event-helper">Dates and details can change. Confirm attendance information with the original source.</p></section>`}

function initializeProfileSections(){const results=el('results'),header=results.querySelector('.ch'),existing=[...results.children].filter(node=>node!==header),tabs=document.createElement('div'),overview=document.createElement('section'),remuneration=document.createElement('section'),capital=document.createElement('section'),projects=document.createElement('section'),jobs=document.createElement('section'),sources=document.createElement('section');tabs.id='profileTabs';tabs.className='profile-tabs';tabs.setAttribute('role','tablist');tabs.setAttribute('aria-label','First Nation profile sections');tabs.innerHTML=[['overview','Overview','Overview'],['remuneration','Remuneration','Pay'],['capital','Community Capital','Capital'],['projects','Housing & Infrastructure','Projects'],['jobs','Jobs & Employment','Jobs'],['sources','Source Documents','Sources']].map(([key,label,shortLabel])=>`<button id="${key}Tab" class="profile-tab${key==='overview'?' active':''}" type="button" role="tab" data-tab="${key}" data-short-label="${shortLabel}" aria-label="${label}" aria-controls="${key}Panel" aria-selected="${key==='overview'}" tabindex="${key==='overview'?'0':'-1'}"><span>${label}</span></button>`).join('');overview.id='overviewPanel';overview.className='profile-panel active';remuneration.id='remunerationPanel';remuneration.className='profile-panel';capital.id='capitalPanel';capital.className='profile-panel';projects.id='projectsPanel';projects.className='profile-panel';jobs.id='jobsPanel';jobs.className='profile-panel';sources.id='sourcesPanel';sources.className='profile-panel';[overview,remuneration,capital,projects,jobs,sources].forEach(panel=>{panel.setAttribute('role','tabpanel');panel.setAttribute('aria-labelledby',`${panel.id.replace('Panel','')}Tab`);panel.tabIndex=0});existing.forEach(node=>remuneration.appendChild(node));header.after(tabs,overview,remuneration,capital,projects,jobs,sources);tabs.addEventListener('click',event=>{const button=event.target.closest('[data-tab]');if(button)switchProfileTab(button.dataset.tab)});tabs.addEventListener('keydown',event=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(event.key))return;const buttons=[...tabs.querySelectorAll('[role="tab"]')],current=buttons.indexOf(document.activeElement);let next=event.key==='Home'?0:event.key==='End'?buttons.length-1:event.key==='ArrowRight'?(current+1)%buttons.length:(current-1+buttons.length)%buttons.length;event.preventDefault();buttons[next].focus();switchProfileTab(buttons[next].dataset.tab)})}
async function switchProfileTab(tab,options={}){if(!VALID_TABS.includes(tab))tab='overview';activeProfileTab=tab;document.querySelectorAll('.profile-tab').forEach(button=>{const active=button.dataset.tab===tab;button.classList.toggle('active',active);button.setAttribute('aria-selected',String(active));button.tabIndex=active?0:-1});document.querySelectorAll('.profile-panel').forEach(panel=>panel.classList.toggle('active',panel.id===`${tab}Panel`));if(tab!=='remuneration')await ensureProfileData();if(tab==='capital'){const current=selectedBand();if(current)curCapitalYear=getCapitalDisplayYear(current)}renderActiveProfilePanel();updateProfileMeta();updateHeaderSource();const band=selectedBand();if(band){window.OpenBandAnalytics?.trackCommunityView(band.name,band.province||'SK',tab==='capital'?getCapitalDisplayYear(band):curYear,band.id);if(tab==='capital')window.OpenBandAnalytics?.trackCommunityCapitalView(band.id,getCapitalDisplayYear(band));if(tab==='jobs')window.OpenBandAnalytics?.trackJobsTab(band.id)}if(!options.history)updateProfileRoute(options.replace?'replace':'push')}
function renderActiveProfilePanel(){const band=selectedBand();if(!band)return;if(activeProfileTab==='overview')renderProfileOverview(band);else if(activeProfileTab==='capital')renderCommunityCapital(band);else if(activeProfileTab==='projects')el('projectsPanel').innerHTML=renderHousingProjectsSection(band);else if(activeProfileTab==='jobs')renderJobsPanel(band);else if(activeProfileTab==='sources')renderSourceDocuments(band)}
function updateProfileMeta(){const band=selectedBand();if(!band)return;updateHeaderContact(band);el('rMeta').innerHTML='';if(activeProfileTab==='remuneration'){const filing=currentFiling(),status=getFilingStatus(filing);addStatusTag(status.label,status.color);if(band.treaty)addStatusTag(band.treaty,'grey');if(filing&&filing.parse_confidence)addStatusTag(`Confidence: ${filing.parse_confidence}`,'grey');return}if(band.treaty)addStatusTag(band.treaty,'grey');if(activeProfileTab==='overview'){const members=memberCountLabel(band.id);addStatusTag(members?`${members} registered band members`:'Registered band members unavailable','grey')}else if(activeProfileTab==='capital'){const year=getCapitalDisplayYear(band),summary=getCapitalSummary(band.id,year),statement=auditedFilingsByYear(band).find(f=>f.year===year&&f.posted),parsed=summary&&summary.parseStatus==='parsed'&&summary.publishable!==false,review=summary&&!parsed;addStatusTag(statement?'Audited statement posted':'Statement not posted',statement?'green':'grey');addStatusTag(parsed?'Capital summary parsed':review?'Manual review needed':'Capital extraction pending',parsed?'green':review?'red':'amber')}else if(activeProfileTab==='projects'){const count=projectsForBand(band.id).length,unverified=unverifiedProjectsForBand(band.id).length;addStatusTag(count?`${count} verified project${count===1?'':'s'}`:'No verified projects yet',count?'green':'grey');if(unverified)addStatusTag(`${unverified} unverified signal${unverified===1?'':'s'}`,'amber')}else addStatusTag(`${getSourceDocuments(band.id).length} source records`,'green')}
function updateHeaderSource(){const band=selectedBand();if(!band)return;const filing=currentFiling(),links=getSourceLinks(band,filing);if(activeProfileTab==='remuneration'){el('rLink').href=links.pdf||links.profile;el('rLink').textContent=links.pdf?'Remuneration PDF':'ISC profile';el('csvBtn').style.display='';el('citeBtn').style.display=''}else if(activeProfileTab==='capital'){const year=getCapitalDisplayYear(band),summary=getCapitalSummary(band.id,year),statement=auditedFilingsByYear(band).find(f=>f.year===year&&f.href),url=summary&&summary.sourceUrl||statement&&statement.href||links.auditedStatement||links.profile;el('rLink').href=url;el('rLink').textContent=url===links.profile?'ISC profile':'Audited statement';el('csvBtn').style.display='none';el('citeBtn').style.display='none'}else if(activeProfileTab==='projects'){const project=projectsForBand(band.id)[0]||unverifiedProjectsForBand(band.id)[0],source=project&&project.sources&&project.sources[0];el('rLink').href=source&&source.url||links.profile;el('rLink').textContent=source?'Latest project source':'ISC profile';el('csvBtn').style.display='none';el('citeBtn').style.display='none'}else if(activeProfileTab==='jobs'){const job=jobsForBand(band.id)[0];el('rLink').href=job&&job.sourceUrl||links.profile;el('rLink').textContent=job?'Official jobs source':'ISC profile';el('csvBtn').style.display='none';el('citeBtn').style.display='none'}else{el('rLink').href=links.profile;el('rLink').textContent=activeProfileTab==='sources'?'ISC filing page':'ISC profile';el('csvBtn').style.display='none';el('citeBtn').style.display='none'}}
function projectDateLabel(value){if(!value)return'';const text=String(value),parts=text.split('-').map(Number);if(parts.length===1)return text;if(parts.length===2){const date=new Date(Date.UTC(parts[0],parts[1]-1,1));return date.toLocaleDateString('en-CA',{year:'numeric',month:'long',timeZone:'UTC'})}const date=new Date(`${text}T12:00:00Z`);return Number.isNaN(date.getTime())?text:date.toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'})}
function projectsForBand(bandId){const priority={'Under Construction':0,Planned:1,Completed:2};return(projectsData.projects||[]).filter(project=>(project.firstNationIds||[]).some(id=>String(id)===String(bandId))).sort((a,b)=>(priority[a.status]??3)-(priority[b.status]??3)||String(b.statusAsOf||b.sources&&b.sources[0]&&b.sources[0].publishedAt||'').localeCompare(String(a.statusAsOf||a.sources&&a.sources[0]&&a.sources[0].publishedAt||''))||String(a.name).localeCompare(String(b.name)))}
function projectTimeline(project){const parts=[];if(project.startDate)parts.push(`Started ${projectDateLabel(project.startDate)}`);if(project.completionDate)parts.push(`Completed ${projectDateLabel(project.completionDate)}`);if(project.expectedCompletionDate)parts.push(`Expected completion ${projectDateLabel(project.expectedCompletionDate)}`);if(project.expectedOpeningDate)parts.push(`Opening scheduled ${projectDateLabel(project.expectedOpeningDate)}`);return parts.join(' · ')}
function projectSourceMarkup(project){return(project.sources||[]).map(source=>{const date=source.publishedAt?`Published ${projectDateLabel(source.publishedAt)}`:source.checkedAt?`Checked ${projectDateLabel(source.checkedAt)}`:'';return`<a href="${escAttr(source.url)}" target="_blank" rel="noopener"><span>${esc(source.name)}</span>${date?`<small>${esc(date)}</small>`:''}</a>`}).join('')}
function projectCardMarkup(project,index){const details=[],timeline=projectTimeline(project);if(project.estimatedCost)details.push(['Estimated Cost',project.estimatedCost]);if(project.funding&&project.funding.length)details.push(['Funding',project.funding.join(' · ')]);if(timeline)details.push(['Dates',timeline]);if(project.unitsCapacity)details.push(['Units / Capacity',project.unitsCapacity]);const extra=index>=3?' project-extra':'';return`<article class="project-row${extra}"${extra?' hidden':''}><div class="project-row-top"><span class="project-category">${esc(project.category||'Community Project')}</span>${project.status?`<span class="project-status status-${slugify(project.status)}">${esc(project.status)}${project.statusAsOf?` <small>as of ${esc(projectDateLabel(project.statusAsOf))}</small>`:''}</span>`:''}</div><h4>${esc(project.name)}</h4><p>${esc(project.description)}</p>${details.length?`<dl class="project-details">${details.map(([label,value])=>`<div><dt>${esc(label)}</dt><dd>${esc(value)}</dd></div>`).join('')}</dl>`:''}<div class="project-sources"><strong>Source${(project.sources||[]).length===1?'':'s'}:</strong>${projectSourceMarkup(project)}</div></article>`}
  function toggleProjects(button){const section=button.closest('.profile-projects'),expanded=button.getAttribute('aria-expanded')==='true';section.querySelectorAll('.project-extra').forEach(row=>row.hidden=expanded);button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'View All Projects':'Show Fewer Projects'}
  function unverifiedProjectsForBand(bandId){return(projectsData.unverifiedProjects||[]).filter(project=>(project.firstNationIds||[]).some(id=>String(id)===String(bandId))).sort((a,b)=>String(b.lastSeenAt||'').localeCompare(String(a.lastSeenAt||''))||String(a.name).localeCompare(String(b.name)))}
  function unverifiedProjectCardMarkup(project,index){const sourceLinks=(project.sources||[]).map(source=>`<a href="${escAttr(source.url)}" target="_blank" rel="noopener"><span>${esc(source.name)}</span>${source.publishedAt?`<small>Published ${esc(projectDateLabel(source.publishedAt))}</small>`:''}</a>`).join(''),extra=index>=3?' unverified-extra':'';return`<article class="unverified-project-row${extra}"${extra?' hidden':''}><div class="project-row-top"><span class="project-category">${esc(project.category||'Community Project')}</span><span class="unverified-label">Unverified</span></div><h4>${esc(project.name)}</h4><p>${esc(project.discussionSummary)}</p><p class="unverified-reason"><strong>Why unverified:</strong> ${esc(project.whyUnverified)}</p><div class="project-sources"><strong>Public signal:</strong>${sourceLinks}</div></article>`}
  function toggleUnverifiedProjects(button){const section=button.closest('.unverified-projects'),expanded=button.getAttribute('aria-expanded')==='true';section.querySelectorAll('.unverified-extra').forEach(row=>row.hidden=expanded);button.setAttribute('aria-expanded',String(!expanded));button.textContent=expanded?'View All Unverified Projects':'Show Fewer Unverified Projects'}
  function renderUnverifiedProjectsSection(band){const projects=unverifiedProjectsForBand(band.id),count=projects.length;return`<section class="unverified-projects" aria-labelledby="unverifiedProjectsHeading"><div class="unverified-heading"><div><h3 id="unverifiedProjectsHeading">Unverified Projects &amp; Community Discussion</h3><p>Source-linked proposals or discussion that are not confirmed projects.</p></div>${count?`<span class="unverified-count">${count} signal${count===1?'':'s'}</span>`:''}</div><div class="unverified-warning"><strong>Not confirmed:</strong> Inclusion here does not mean funding, approval, construction or delivery is secured. Details may change or never proceed.</div>${count?`<div class="unverified-project-list">${projects.map(unverifiedProjectCardMarkup).join('')}</div>${count>3?`<div class="project-actions"><button class="small-btn" type="button" aria-expanded="false" onclick="toggleUnverifiedProjects(this)">View All Unverified Projects</button></div>`:''}`:`<div class="unverified-empty">No source-linked unverified project discussion was indexed in the current public-source scan.</div>`}</section>`}
  function renderHousingProjectsSection(band){if(activeProfileTab==='overview')return'';const projects=projectsForBand(band.id),count=projects.length;return`<section class="profile-projects" aria-labelledby="projectsHeading"><div class="section-head"><div><h3 id="projectsHeading">Housing &amp; Infrastructure Projects</h3><p>Current and recently completed projects found in verifiable public sources.</p></div>${count?`<span class="project-count">${count} project${count===1?'':'s'}</span>`:''}</div>${count?`<div class="project-list">${projects.map(projectCardMarkup).join('')}</div>${count>3?`<div class="project-actions"><button class="small-btn" type="button" aria-expanded="false" onclick="toggleProjects(this)">View All Projects</button></div>`:''}`:`<div class="projects-empty">No current or recently completed project has been added from a verifiable public source yet.</div>`}${renderUnverifiedProjectsSection(band)}</section>`}
function jobDate(value){if(!value)return null;const date=new Date(`${String(value).slice(0,10)}T12:00:00Z`);return Number.isFinite(date.getTime())?date:null}
function effectiveJobStatus(job){const closing=jobDate(job.closingDate),checked=jobDate(job.lastChecked),today=new Date();today.setHours(0,0,0,0);if(closing){const days=Math.ceil((closing-today)/86400000);if(days<0)return'Closed';if(days<=7)return'Closing soon';return'Open'}if(job.status==='Closed')return'Closed';if(['Open','Closing soon','Date unavailable'].includes(job.status)){if(checked&&(today-checked)/86400000<=21)return job.status;return'Pending verification'}return'Pending verification'}
function jobDateLabel(value){const date=jobDate(value);return date?date.toLocaleDateString('en-CA',{year:'numeric',month:'short',day:'numeric',timeZone:'UTC'}):'Date not published'}
function jobsForBand(bandId){return(jobsData.listings||[]).filter(job=>String(job.communityId)===String(bandId)||(job.firstNationIds||[]).some(id=>String(id)===String(bandId))).map(job=>({...job,status:effectiveJobStatus(job)})).filter(job=>['Open','Closing soon','Date unavailable'].includes(job.status)).sort((a,b)=>String(b.postedDate||b.lastChecked||'').localeCompare(String(a.postedDate||a.lastChecked||''))||String(a.title).localeCompare(String(b.title)))}
function openJobsForBand(bandId){return jobsForBand(bandId).filter(job=>['Open','Closing soon'].includes(job.status))}
function employmentProgramsForBand(bandId){return(jobsData.employmentPrograms||[]).filter(item=>String(item.communityId)===String(bandId))}
function jobMeta(job){return[job.employmentType,job.location,job.workplaceType].filter(Boolean).map(esc).join(' · ')}
function trackJobLink(kind,jobId,url){const band=selectedBand(),job=(jobsData.listings||[]).find(item=>item.id===jobId);if(kind==='application')window.OpenBandAnalytics?.trackJobApplication(jobId,url,band&&band.id);else window.OpenBandAnalytics?.trackJobOpen(jobId,url,band&&band.id);return true}
